                        <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Execution Duration (Hrs)</span>
                        <input 
                            type="number" 
                            value={algoDuration}
                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
                            className="bg-zinc-950 border border-white/10 rounded-lg w-16 text-center text-xs font-mono font-bold text-white py-1 outline-none focus:border-purple-500"
                        />
                     </div>

                     <div className="relative h-4 w-full flex items-center">
                        <input 
                            type="range" 
                            min="0.5" 
                            max="24" 
                            step="0.5"
                            value={algoDuration} 
                            onChange={(e) => setAlgoDuration(parseFloat(e.target.value))}
