                            style={{ height: '4px' }}
                        />
                     </div>

                     <div className="mt-4 flex items-center justify-between border-t border-white/5 pt-3">
                         <div className="flex items-center gap-1.5 text-[9px] font-bold text-purple-400 uppercase tracking-wide">
                             <Split size={12} />
                             <span>{simulation.numTranches} Tranches</span>
                         </div>
                         <div className="text-[9px] font-mono text-zinc-500 tabular-nums">
                             ~1 tx every {simulation.avgIntervalMins} mins
                         </div>
                     </div>
                  </div>

                  {/* RANDOMIZE (Outline Icon) */}
                  <div 
                     onClick={() => setAlgoRandomize(!algoRandomize)}
                     className={`p-4 rounded-xl border cursor-pointer transition-all flex items-center justify-between group ${algoRandomize ? 'bg-purple-500/10 border-purple-500/30' : 'bg-zinc-900/50 border-white/5'}`}
                  >
                     <div className="flex items-center gap-3">
                        <Shuffle size={20} strokeWidth={1.5} className="text-gray-500 group-hover:text-gray-300" />
                        <div>
                           <p className={`text-[10px] font-black uppercase tracking-widest ${algoRandomize ? 'text-purple-300' : 'text-zinc-500'}`}>Randomize Intervals</p>
                           <p className="text-[10px] text-zinc-500 leading-tight">Sandwich Protection</p>
                        </div>
