                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* MEV Footer */}
                        {hasAmount && (
                            <div className="mt-4 pt-3 border-t border-white/5 flex items-center justify-between relative z-20 animate-in fade-in slide-in-from-bottom-1">
