                                    <span>MEV Protected</span>
                                </div>
                                <div className="text-[9px] text-zinc-600 font-mono">
                                    Latency: 2ms
                                </div>
                            </div>
                        )}

                    </div>

                    {/* 2. Cost Structure */}
                    <div className="bg-zinc-900/40 border border-white/5 rounded-xl p-4 flex flex-col min-h-[160px]">
                        <div className="flex items-center gap-2 mb-4">
                            <Coins className="w-3 h-3 text-gray-500" />
                            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Cost Structure</span>
                        </div>

                        <div className="flex flex-col gap-2 mt-auto text-xs">
                            <div className="flex justify-between">
                                <span className="text-gray-500">Max Slippage</span>
                                {/* Interactive Slippage */}
                                <span 
                                    onClick={openSettingsModal}
                                    title="Click to adjust slippage tolerance"
                                    className="text-gray-300 decoration-dashed underline underline-offset-2 cursor-pointer hover:text-white transition-colors"
                                >
                                    Auto ({simulation.liquidityBuffer})
                                </span>
                            </div>
                            <div className="flex justify-between"><span className="text-gray-500">Network Fee</span><span className="text-white font-mono tabular-nums">~{formatMoney(BASE_GAS_COST_USD)}</span></div>

                            {/* Conditional Impact */}
                            <div className="flex justify-between">
                                <span className="text-gray-500">Price Impact</span>
                                <span className={`${hasAmount ? 'text-red-400' : 'text-zinc-600'} font-mono tabular-nums`}>
                                    {hasAmount ? `-${simulation.swapImpactPct.toFixed(2)}%` : '—'}
                                </span>
                            </div>

                            <div className="h-px bg-white/5 my-1"></div>

                            {/* Conditional Total Cost */}
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-300 font-medium">Est. Loss (Gas + Impact)</span>
                                <span className={`${hasAmount ? 'text-white' : 'text-zinc-600'} font-bold font-mono tabular-nums`}>
                                    {hasAmount ? formatMoney(simulation.totalSwapCost) : '—'}
                                </span>
                            </div>
                        </div>
                    </div>

                </div>
             </>
          )}

      </section>
    </div>
  );
};

