        { dex: 'SushiSwap', pct: 10, color: 'bg-zinc-700', rate: 3205.00, impact: 0.15 }
    ];

    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isBelowMarketSell = distanceToMarket < 0; 

    // Limit Logic (Mock)
    let execProbability = 0;
    let probLabel = 'LOW';
    let probColor = 'text-zinc-500';
    let timeHorizon = '> 4 Days';
    let timeRange = '3d - 7d';

    if (isBelowMarketSell) {
        execProbability = 100;
        probLabel = 'IMMEDIATE';
        probColor = 'text-orange-500';
        timeHorizon = 'Instant';
        timeRange = 'Now';
    } else {
        if (distanceToMarket < 0.5) {
            execProbability = 92;
            probLabel = 'VERY HIGH';
            probColor = 'text-emerald-400';
            timeHorizon = '< 1 Hour';
            timeRange = '10m - 90m';
        } else if (distanceToMarket < 1.5) {
            execProbability = 75;
            probLabel = 'HIGH';
            probColor = 'text-emerald-500';
            timeHorizon = '~12 Hours';
            timeRange = '4h - 24h';
        } else if (distanceToMarket < 3.0) {
            execProbability = 45;
            probLabel = 'MEDIUM';
            probColor = 'text-amber-500';
            timeHorizon = '~2 Days';
            timeRange = '12h - 4d';
        } else {
            execProbability = 12;
            probLabel = 'LOW';
            probColor = 'text-rose-500';
            timeHorizon = '> 4 Days';
            timeRange = '3d - GTC';
        }
    }

    const dailyYieldLoss = (limitValue * RISK_FREE_RATE) / 365;
    const wallsAheadUsd = Math.abs(distanceToMarket) * 8_000_000; 

    let structureLabel = 'IN RANGE';
    let structureColor = 'text-zinc-400';
    if (limitP < SUPPORT_LEVEL) {
        structureLabel = 'BELOW SUPPORT'; 
        structureColor = 'text-orange-400';
    } else if (limitP > RESISTANCE_LEVEL) {
        structureLabel = 'BREAKOUT TARGET';
        structureColor = 'text-emerald-400'; 
    }

    const scheduleData = [];
    if (optimalTranches > 0) {
        let currentTime = new Date();
        const now = new Date();
        const startTime = new Date(now.getTime() - (avgIntervalMins * 60000 * 2)); 
        currentTime = startTime;

        let predictedPrice = ETH_PRICE;

        for (let i = 0; i < optimalTranches; i++) {
             let variance = 1;
             if (algoRandomize) variance = 0.8 + Math.random() * 0.4; 

             let status: 'executed' | 'active' | 'pending' = 'pending';
             if (i < 2) status = 'executed';
             if (i === 2) status = 'active';

             // Fake price decay impact simulation
             predictedPrice = predictedPrice * (1 - (0.0002 + (Math.random() * 0.0001)));

             scheduleData.push({
                 id: i,
                 time: currentTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
                 volume: trancheSizeETH * variance,
                 status: status,
                 priceDecay: predictedPrice // Overlay line logic
             });
             currentTime = new Date(currentTime.getTime() + avgIntervalMins * 60000);
        }
    }

    let finalReceive = '0.00';
    let receiveValNum = 0;

    if (tradeMode === 'limit') {
        finalReceive = formatTokenAmount(limitValue);
        receiveValNum = limitValue;
    } else if (tradeMode === 'algo') {
        const val = usdValue - totalAlgoCost;
        finalReceive = formatTokenAmount(val);
        receiveValNum = val;
    } else {
        const val = usdValue - totalSwapCost;
        finalReceive = formatTokenAmount(val);
        receiveValNum = val;
    }

    const minReceived = receiveValNum * (1 - slippage/100);

    return {
        usdValue,
        limitValue,
        receiveAmount: finalReceive,
        receiveValNum,
        minReceived,
        swapImpactPct,
        swapImpactCost, // Instant Dump Cost
        algoTrancheImpactPct,
        totalAlgoCost, // Strategy Cost
        platformFee, // NEW: Fee value
        numTranches: optimalTranches,
        avgIntervalMins,
        algoTotalGas,
        swapTotalGas,
        netSavings,
        isAlgoEfficient,
        scheduleData,
        routingScore,
        routeSplit,
        totalSwapCost,
        distanceToMarket,
        isBelowMarketSell,
        execProbability,
        probLabel,
        probColor,
        timeHorizon,
        timeRange,
        dailyYieldLoss,
        structureLabel,
        structureColor,
        wallsAheadUsd,
        liquidityBuffer: `${slippage}%`
    };
  }, [payAmount, tradeMode, algoDuration, limitPrice, algoRandomize, slippage]);


  // ... (Handlers and Effects remain same)
  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
