    // Or scale linearly for the demo
    let swapImpactPct = 0;
    if (usdValue > 0) {
        // Base slippage + volume penalty
        // For $800k -> ~1.2%
        swapImpactPct = Math.min((usdValue / 800000) * 1.2, 15);
