                                    </div>
                                    <button 
                                        onClick={() => setAlgoMinPrice(ETH_PRICE.toFixed(2))}
                                        className="text-[9px] uppercase font-bold text-zinc-500 hover:text-emerald-500 bg-zinc-800/50 px-1.5 py-0.5 rounded border border-white/5 transition-colors"
                                    >
                                        Market
                                    </button>
                                </div>
                            </div>

                            <div 
                                className="bg-zinc-950/30 border border-white/5 rounded-xl p-3 flex items-center justify-between cursor-pointer hover:border-white/10 transition-colors group h-[60px]" 
                                onClick={() => setAlgoRandomize(!algoRandomize)}
                            >
                                <div className="flex flex-col gap-0.5">
                                    <label className={`text-[9px] font-bold uppercase cursor-pointer tracking-wide transition-colors ${algoRandomize ? 'text-purple-400' : 'text-zinc-500'}`}>Randomize Intervals</label>
                                    <span className="text-[8px] font-bold text-zinc-600 uppercase tracking-wider">Anti-Frontrunning</span>
                                </div>
                                <div className={`w-8 h-4 rounded-full relative transition-colors ${algoRandomize ? 'bg-purple-600' : 'bg-zinc-700'}`}>
                                    <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-all duration-300 shadow-sm ${algoRandomize ? 'left-4.5' : 'left-0.5'}`}></div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <button 
                        onClick={() => setIsAlgoRunning(true)}
                        disabled={numericPay <= 0 || isInsufficientBalance}
                        className={`mt-4 w-full py-4 rounded-xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl transition-all active:scale-[0.98] ${
                            isInsufficientBalance || numericPay <= 0 
                            ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed border border-white/5' 
                            : 'bg-purple-600 text-white hover:bg-purple-500 shadow-purple-500/20'
                        }`}
                    >
                        LAUNCH {algoStrategy} STRATEGY
                    </button>
                </div>
            ) : (
                <div className="flex-1 flex flex-col gap-4">
                    <div className="bg-zinc-900/40 border border-white/5 rounded-2xl p-5 space-y-6 shadow-xl backdrop-blur-sm">
                        <div className="space-y-4">
                            <div className="flex justify-between items-start">
                                <div className="flex flex-col gap-2 w-full">
                                     <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest flex justify-between w-full pr-1">
                                        <span>You Pay</span>
                                        <span className="font-mono text-zinc-500">Bal: {formatToken(ETH_BALANCE)}</span>
                                     </label>
                                     <div className="flex items-center gap-3">
                                        <input 
                                            type="text" 
                                            value={payAmount}
                                            onChange={handleAmountChange}
                                            className="text-4xl lg:text-5xl font-mono font-medium tracking-tighter bg-transparent outline-none placeholder:text-zinc-800 text-white w-full min-w-0" 
                                            placeholder="0.00" 
                                        />
                                        <button className="flex items-center gap-2 bg-zinc-950/50 border border-white/10 px-3 py-2 rounded-xl hover:border-white/20 transition-colors shrink-0">
                                            <img src={ETH_ICON} className="w-5 h-5 object-contain" alt="ETH" />
                                            <span className="font-bold text-white text-sm">ETH</span>
                                            <ChevronDown size={12} className="text-zinc-600" />
                                        </button>
                                     </div>
                                     <div className="flex gap-2 mt-1">
                                        {[25, 50, 75, 100].map(pct => (
                                            <button 
                                                key={pct}
                                                onClick={() => handlePercentageClick(pct)}
                                                className="border border-white/10 text-[10px] font-bold text-zinc-500 px-3 py-1 rounded-md hover:bg-white/5 hover:text-white transition-colors"
                                            >
                                                {pct === 100 ? 'MAX' : `${pct}%`}
                                            </button>
                                        ))}
                                     </div>
                                </div>
                            </div>

                            <div className="relative h-px bg-white/5 w-full my-2">
                                <div className="absolute left-1/2 -translate-x-1/2 -top-3 p-1.5 bg-[#0e0e11] border border-white/10 rounded-full text-zinc-500 shadow-sm">
                                    <ArrowDown size={12} />
                                </div>
                            </div>

                            <div className="flex justify-between items-end">
                                <div className="flex flex-col gap-2 w-full">
                                     <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Estimated Receive</label>
                                     <div className="flex items-center gap-3">
                                        <div className="text-3xl lg:text-4xl font-mono font-medium tracking-tighter text-zinc-300 w-full min-w-0 truncate">
                                            {payAmount ? formatTokenAmount(simulation.receiveValNum) : '0.00'}
                                        </div>
                                        <button className="flex items-center gap-2 bg-zinc-950/50 border border-white/5 px-3 py-2 rounded-xl hover:border-white/10 transition-colors shrink-0">
                                            <img src={USDC_ICON} className="w-5 h-5 object-contain" alt="USDC" />
                                            <span className="font-bold text-white text-sm">USDC</span>
                                            <ChevronDown size={12} className="text-zinc-600" />
                                        </button>
                                     </div>
                                     <div className="mt-1 text-[9px] font-mono font-bold text-zinc-600">
                                        Min. Receive (after {slippage}% slippage): {formatTokenAmount(simulation.minReceived)} USDC
                                     </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {tradeMode === 'limit' && (
                        <div className="bg-zinc-900 border border-white/5 rounded-2xl p-5 shadow-inner">
                            <label className="text-[9px] font-bold text-zinc-500 uppercase block mb-2 tracking-wide">Limit Price</label>
                            <div className="flex items-center gap-3">
                                <span className="text-zinc-500 font-mono">$</span>
                                <input 
                                    type="text" 
                                    value={limitPrice}
                                    onChange={(e) => setLimitPrice(e.target.value)}
                                    className="bg-transparent text-xl font-mono font-bold text-white outline-none w-full"
                                />
                                <button className="text-[10px] font-bold text-emerald-500 bg-emerald-500/10 px-2 py-1 rounded uppercase">Current</button>
                            </div>
                        </div>
                    )}

                    <button 
                        disabled={numericPay <= 0 || isInsufficientBalance}
                        className={`mt-4 w-full py-4 rounded-xl font-black text-[11px] uppercase tracking-[0.2em] shadow-xl transition-all active:scale-[0.98] ${
                            isInsufficientBalance || numericPay <= 0 
                            ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed border border-white/5' 
                            : 'bg-emerald-500 text-black hover:bg-emerald-400 shadow-emerald-500/20'
                        }`}
                    >
                        {tradeMode === 'limit' ? 'PLACE LIMIT ORDER' : 'SWAP NOW'}
                    </button>
                </div>
            )}
          </div>
          )}
        </div>
      </section>

      {/* RIGHT PANEL: CHART & ANALYSIS */}
      <section className="lg:col-span-6 flex flex-col h-full gap-6">
          {/* Chart Container */}
          <div className="bg-zinc-900/40 border border-white/5 rounded-2xl p-6 shadow-xl backdrop-blur-md flex-1 min-h-[400px] flex flex-col">
              <div className="flex justify-between items-center mb-6">
                  <div className="flex items-center gap-2">
                      <img src={ETH_ICON} className="w-6 h-6" alt="ETH" />
                      <span className="text-sm font-bold text-white">ETH / USDC</span>
                  </div>
                  <div className="flex gap-2">
                      {['1H', '1D', '1W', '1M'].map(t => (
                          <button key={t} className="px-2 py-1 bg-zinc-800 rounded text-[10px] font-bold text-zinc-400 hover:text-white transition-colors">{t}</button>
                      ))}
                  </div>
              </div>
              <div className="flex-1 w-full relative">
                 <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={marketChartData}>
                        <defs>
                            <linearGradient id="colorPrice" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#09090b', borderColor: '#27272a', color: '#fff' }}
                            itemStyle={{ color: '#fff' }}
                        />
                        <Area type="monotone" dataKey="value" stroke="#10b981" fillOpacity={1} fill="url(#colorPrice)" />
                    </AreaChart>
                 </ResponsiveContainer>
              </div>
          </div>

          {/* Route Analysis */}
          <div className="bg-zinc-900/40 border border-white/5 rounded-2xl p-6 shadow-xl backdrop-blur-md">
              <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-4">Smart Routing</h3>
              <div className="space-y-3">
                  {simulation.routeSplit.map((route, i) => (
                      <div key={i} className="flex items-center gap-3">
                          <div className="w-1 h-8 rounded-full" style={{ backgroundColor: route.color }}></div>
                          <div className="flex-1">
                              <div className="flex justify-between items-center">
                                  <span className="text-xs font-bold text-white">{route.dex}</span>
                                  <span className="text-xs font-mono font-bold text-zinc-300">{route.pct}%</span>
                              </div>
                              <div className="w-full h-1 bg-zinc-800 rounded-full mt-1 overflow-hidden">
                                  <div className="h-full" style={{ width: `${route.pct}%`, backgroundColor: route.color }}></div>
                              </div>
                          </div>
                          <div className="text-right">
                              <div className="text-[10px] font-mono text-zinc-500">Rate: {route.rate}</div>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      </section>
    </div>
  );
};

export default ExecutionView;
